<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,ref} from 'vue';import type {LocalLauncherClient} from '../local-api';
import {ServerCallError,unwrapServerResult,type ServerStatus,type CloudAccount} from '../../../../dispatch-core/src/main/typescript/server-contract';
const props=defineProps<{client:LocalLauncherClient}>();const status=ref<ServerStatus|null>(null),account=ref<CloudAccount|null>(null),username=ref(''),display=ref(''),password=ref(''),busy=ref(false),error=ref(''),notice=ref('');let alive=true;const lifetime=new AbortController();
const valid=computed(()=>/^[a-z0-9_]{3,32}$/.test(username.value)&&Array.from(password.value).length>=15&&Array.from(password.value).length<=128);
async function api<T>(path:string,body?:Record<string,unknown>){return unwrapServerResult<T>(await props.client.serverCall(path,body,lifetime.signal));}
async function refresh(){if(busy.value)return;busy.value=true;error.value='';try{const s=await api<ServerStatus>('/status');if(!alive)return;status.value=s;if(s.enabled&&s.source==='LIVE'){try{const a=await api<CloudAccount>('/account');if(alive)account.value=a;}catch(e){if(e instanceof ServerCallError&&e.code==='AUTH_FAILED'){account.value=null;}else throw e;}}}catch(e){if(alive)error.value=(e as Error).message;}finally{if(alive)busy.value=false;}}
async function submit(action:'register'|'login'|'logout'){
 if(busy.value)return;busy.value=true;error.value='';notice.value='';try{if(action==='logout'){await api('/account/logout',{});if(alive){account.value=null;notice.value='已退出三秋叶账号，游戏身份保持。';}}
 else{const result=await api<CloudAccount>('/account/'+action,{username:username.value,password:password.value,...(action==='register'?{displayName:display.value.trim(),operationId:crypto.randomUUID()}:{})});if(alive){account.value=result;notice.value=action==='register'?'已在账号服务注册，管理面板可以读取公开资料。':'已登录三秋叶账号。';}}
 }catch(e){if(alive){error.value=(e as Error).message+(action==='register'?'；若结果未能确认，请先尝试登录，避免重复注册。':'');if(action==='logout')account.value=null;}}finally{password.value='';if(alive)busy.value=false;}}
onMounted(refresh);onBeforeUnmount(()=>{alive=false;password.value='';lifetime.abort();});
</script>
<template><section v-if="status?.source!=='MOCK'" class="cloud-account-card launcher-glass" aria-label="三秋叶云端账号"><header><div><span class="launcher-overline">SAN QIU YE ACCOUNT</span><h2>三秋叶账号</h2><p>用于管理员整合包和服务，与Minecraft游戏身份分别管理。</p></div><button class="launcher-secondary" :disabled="busy" @click="refresh">{{busy?'正在连接…':'检查连接'}}</button></header><p v-if="error" role="alert" class="launcher-inline-notice">{{error}}</p><p v-if="notice" role="status">{{notice}}</p>
 <p v-if="!status" role="status">正在读取账号服务配置…</p><p v-else-if="!status.enabled" class="launcher-caption">账号服务尚未配置，当前仍可使用本机游戏；请配置安全服务地址后注册。</p>
 <div v-else-if="account" class="cloud-account-summary"><div><h3>{{account.displayName}}</h3><p>@{{account.username}} · {{account.groupId}}</p><small>最近连接：{{new Date(account.lastSeenAt).toLocaleString()}}</small></div><button class="launcher-secondary" data-cloud-logout :disabled="busy" @click="submit('logout')">退出账号</button></div>
 <form v-else class="cloud-account-form" @submit.prevent="submit('register')"><label>用户名<input v-model="username" data-cloud-username autocomplete="username" maxlength="32" placeholder="3–32位小写字母、数字或下划线" :disabled="busy"></label><label>显示名<input v-model="display" data-cloud-display autocomplete="nickname" maxlength="64" placeholder="管理面板中显示的名字" :disabled="busy"></label><label>口令<input v-model="password" data-cloud-password type="password" autocomplete="off" maxlength="256" placeholder="15–128个字符，可含空格和中文" :disabled="busy"></label><div class="cloud-account-actions"><button type="submit" class="launcher-primary" data-cloud-register :disabled="busy||!valid||!display.trim()">注册账号</button><button type="button" class="launcher-secondary" data-cloud-login :disabled="busy||!valid" @click="submit('login')">已有账号，登录</button></div><p class="launcher-caption">仅发送三秋叶账号所需资料，不发送微软凭据、游戏存档或自己的整合包。当前会话仅保存在后台内存，重开后需重新登录。</p></form>
 </section></template>
<style scoped>.cloud-account-card{padding:24px;border-radius:24px;margin-bottom:24px}.cloud-account-card header,.cloud-account-summary{display:flex;justify-content:space-between;gap:20px;align-items:center}.cloud-account-card h2{margin:8px 0}.cloud-account-card p{line-height:1.7}.cloud-account-form{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.cloud-account-form label{display:grid;gap:8px}.cloud-account-form input{min-width:0;max-width:100%;width:100%;box-sizing:border-box;padding:12px;border:1px solid var(--glass-line,#b9cfc1);border-radius:12px;color:inherit;background:var(--glass-dialog,#fff)}.cloud-account-actions{display:flex;gap:12px;flex-wrap:wrap;grid-column:1/-1}.cloud-account-form>p{grid-column:1/-1;margin:0}@media(max-width:1000px){.cloud-account-form{grid-template-columns:1fr}.cloud-account-card header{align-items:start;flex-wrap:wrap}}</style>
